import { notFound } from "next/navigation";
import Header from "../../components/Header";
import ProductButton from "../../components/ProductButton";
import { certBySlug, certifications } from "../../data/certifications";
import { products } from "../../data/products";
import { articles } from "../../data/articles";

export function generateStaticParams() {
  return certifications.filter((cert) => cert.enabled).map((cert) => ({ slug: cert.slug }));
}

export async function generateMetadata({ params }) {
  const { slug } = await params;
  const cert = certBySlug[slug];

  if (!cert) return {};

  return {
    title: `${cert.name}は最短${cert.shortest}｜合格時間と教材`,
    description: `${cert.name}の最短合格目安は${cert.shortest}。最短で進めるUdemy教材と、詳しい根拠をまとめたnoteへの導線を掲載しています。`
  };
}

export default async function CertificationPage({ params }) {
  const { slug } = await params;
  const cert = certBySlug[slug];
  if (!cert || !cert.enabled) return notFound();

  const certProducts = (cert.productIds || []).map((id) => products[id]).filter(Boolean);
  const primaryProduct = certProducts[0];

  return (
    <main className="certPage">
      <Header />

      <section className="hero compact shell certHero">
        <a className="back" href="/">← 資格一覧</a>
        <p className="overline">{cert.category} / SHORTEST TIME</p>
        <h1>{cert.name}</h1>

        <div className="timeHero">
          <span>最短合格目安</span>
          <strong>{cert.shortest}</strong>
        </div>

        <p className="heroText">{cert.summary}</p>

        {primaryProduct && (
          <div className="heroCta">
            <ProductButton product={primaryProduct} certName={cert.name} />
            <p className="ctaSub">教材を探し回らず、まず1つに絞って始める。</p>
          </div>
        )}
      </section>

      {certProducts.length > 1 && (
        <section className="shell routeSection">
          <p className="sectionTitle">教材</p>
          <div className="productList">
            {certProducts.map((product, index) => (
              <article className="productRow" key={product.name}>
                <div>
                  <span className="productNo">{String(index + 1).padStart(2, "0")}</span>
                  <h2>{product.name}</h2>
                  <p>{product.reason}</p>
                </div>
                <ProductButton product={product} certName={cert.name} />
              </article>
            ))}
          </div>
        </section>
      )}

      {cert.articleIds.length > 0 && (
        <section className="shell detailSection noteSection">
          <p className="sectionTitle">この時間の根拠を見る</p>
          <p className="sectionLead">短期合格者の事例・勉強時間・比較はnoteにまとめています。</p>
          <div className="articleList">
            {cert.articleIds.map((id) => {
              const article = articles[id];
              if (!article) return null;
              return (
                <a href={article.url} className="articleRow" target="_blank" rel="noreferrer" key={id}>
                  <span>{article.title}</span><b>↗</b>
                </a>
              );
            })}
          </div>
        </section>
      )}

      {cert.nextCerts.length > 0 && (
        <section className="shell nextSection">
          <p className="sectionTitle">次に取るなら</p>
          {cert.nextCerts.map((nextSlug) => {
            const next = certBySlug[nextSlug];
            if (!next) return null;
            return (
              <a className="nextRow" href={`/${next.slug}`} key={next.slug}>
                <span>{next.name}</span><span>{next.shortest} →</span>
              </a>
            );
          })}
        </section>
      )}

      <section className="shell disclosure">
        <strong>PR</strong>
        <p>このページにはアフィリエイト広告が含まれます。</p>
      </section>

      <footer className="footer shell">© 2026 ponpokoken.com</footer>

      {primaryProduct && (
        <div className="mobileStickyCta">
          <ProductButton product={primaryProduct} certName={cert.name} sticky />
        </div>
      )}
    </main>
  );
}
